--- app/streamlit_app.py ---
"""The officer's queue -- the demo UI.

RUNTIME. Run with::

    streamlit run app/streamlit_app.py

**This is the officer's view, not a chatbot.** The human queue is where a reviewer
actually works, so the screen is organised around the two things they do: confirm
what was automated, and act on what was not. An escalated item is therefore not a
failure state to be hidden -- it is the primary content (``BUILD.md`` S5.9).

Three commitments the layout makes good on:

* **Every escalated item carries a reason chip.** An officer sorting a queue needs
  to know why an item is in front of them before they open it, and the reason is
  closed vocabulary rather than free text, so the queue can be grouped by it.
* **The SOP pane renders the retrieved procedure in full.** This is what makes a
  drafting failure workable rather than dead: the officer writes the reply from the
  same source the drafter would have used.
* **Drafts are live.** Free-tier rate limits are visible here rather than hidden --
  a rate-limited item shows its failure reason and its SOP, which is the designed
  behaviour and not a defect to apologise for.

The risk-coverage slider re-routes already-classified items through the REAL router
at a new threshold multiplier. Nothing is re-classified, so the slider is instant
and the curve it traces is the one the system would actually follow.
"""

from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

import streamlit as st

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "src"))
sys.path.insert(0, str(ROOT))

from triage.env import load_env  # noqa: E402

load_env()

from eval.dataset import split  # noqa: E402

from triage.graph import build_default_deps, build_graph, run_one  # noqa: E402
from triage.models.calibration import TemperatureScaler  # noqa: E402
from triage.models.encoder import ModelNotTrainedError  # noqa: E402
from triage.nodes.calibrate import calibrate, rollup  # noqa: E402
from triage.nodes.flags import detect_flags  # noqa: E402
from triage.nodes.route import load_thresholds, route  # noqa: E402
from triage.pii.scrubber import Scrubber  # noqa: E402
from triage.schemas import Action, TriageState  # noqa: E402
from triage.sop.index import build_index  # noqa: E402

RESULTS = ROOT / "eval" / "results"

st.set_page_config(
    page_title="Citizen triage â€” officer queue",
    layout="wide",
    initial_sidebar_state="expanded",
)

#: Queue styling. Density is the point: an officer sorting a queue wants many items
#: on screen at once, and the default Streamlit button is tall, centred and heavy.
#: These rules restyle the row buttons into flush-left list rows -- borderless, tight
#: leading, a hairline between them -- so roughly three times as many items are
#: visible without changing what a row says.
#:
#: Colour is carried by the chips rather than the rows: an escalated item is already
#: distinguished by sitting in the review queue, so tinting whole rows would spend
#: the screen's only strong colour on a distinction the tab already makes. All
#: colours are set against both themes, since a fixed palette would invert badly
#: for anyone running Streamlit in dark mode.
#: The row hook is Streamlit's own ``st-key-<key>`` class, which it stamps on the
#: element container for any keyed widget. That is a documented, stable handle;
#: matching on emotion hashes or on sibling position would break on a version bump.
#: Row keys are prefixed ``qrow-``, so these rules touch the queue and nothing else.
_QUEUE_CSS = """
<style>
/* The queue rows. Streamlit renders each as a button; these strip the button
   chrome and leave a flush-left list row. */
div[class*="st-key-qrow-"] button {
    text-align: left !important;
    justify-content: flex-start !important;
    align-items: flex-start !important;
    padding: 5px 10px !important;
    margin: 0 !important;
    border: none !important;
    border-bottom: 1px solid rgba(128, 128, 128, 0.18) !important;
    border-radius: 0 !important;
    background: transparent !important;
    font-weight: 400 !important;
    line-height: 1.3 !important;
    min-height: 0 !important;
    height: auto !important;
}
div[class*="st-key-qrow-"] button:hover {
    background: rgba(128, 128, 128, 0.12) !important;
}
div[class*="st-key-qrow-"] button:focus {
    box-shadow: none !important;
    outline: none !important;
}
/* Collapse the gap Streamlit reserves between stacked widgets so rows sit flush. */
div[class*="st-key-qrow-"] { margin-top: -0.75rem !important; }

/* Streamlit centres a button's label with FLEXBOX, not text-align, and it does so
   on two unnamed wrappers between the button and the markdown -- a div and a span,
   both ``justify-content: center``. Overriding text-align alone leaves the label
   centred; these have to be reset to flex-start and given the full width, or they
   shrink-wrap and re-centre. */
div[class*="st-key-qrow-"] button > div,
div[class*="st-key-qrow-"] button > div > span {
    justify-content: flex-start !important;
    align-items: flex-start !important;
    width: 100% !important;
}
div[class*="st-key-qrow-"] button div[data-testid="stMarkdownContainer"] {
    width: 100% !important;
    text-align: left !important;
}

/* Line one is the subject (bold, slightly larger), line two the status and
   sender. Both live in ONE markdown paragraph separated by a hard break, so the
   status line is coloured through Streamlit's own ``:orange[...]`` markdown in
   the label rather than from here -- a <br>-separated line cannot be selected in
   CSS. */
div[class*="st-key-qrow-"] button p {
    margin: 0 !important;
    padding-left: 0 !important;
    text-indent: 0 !important;
    text-align: left !important;
    width: 100% !important;
    font-size: 0.78rem !important;
    line-height: 1.35 !important;
}
div[class*="st-key-qrow-"] button p strong { font-size: 0.84rem; font-weight: 600; }

/* The selected row: a left rule and a tint, so the list echoes what the detail
   pane is showing. Without this, selection lived only in session_state and the
   queue gave no sign of which item was open. */
div[class*="st-key-qrow-sel-"] button {
    background: rgba(56, 122, 223, 0.16) !important;
    box-shadow: inset 3px 0 0 0 #387adf !important;
}
div[class*="st-key-qrow-sel-"] button p { font-weight: 600 !important; }

/* The metric strip: smaller, so it reads as a status bar rather than a dashboard.
   The contribution is the queue and the curve, not these three numbers. */
div[data-testid="stMetricValue"] { font-size: 1.45rem !important; }
div[data-testid="stMetricLabel"] { font-size: 0.75rem !important; opacity: 0.75; }

/* Tighten the top padding Streamlit reserves above the title. */
div.block-container { padding-top: 2.6rem !important; }
</style>
"""
st.markdown(_QUEUE_CSS, unsafe_allow_html=True)


# --------------------------------------------------------------------------- #
# Loading. Cached, because the corpus and the weights load once per session.
# --------------------------------------------------------------------------- #


@st.cache_resource
def _index() -> Any:
    return build_index()


@st.cache_resource
def _scrubber() -> Scrubber:
    return Scrubber()


@st.cache_resource
def _classifier() -> Any:
    """The fine-tuned encoder. Absent weights are a message, not a traceback."""
    from triage.models.encoder import EncoderClassifier

    return EncoderClassifier()


@st.cache_data(show_spinner="Classifying the inbox â€¦")
def _triage(split_name: str, limit: int) -> list[dict[str, Any]]:
    """Scrub, classify, roll up and calibrate every email ONCE.

    Routing is deliberately left out: the slider re-routes these rows without
    re-classifying, which is what keeps it interactive and what guarantees the
    displayed decision comes from the real router rather than a copy of its rule.
    """
    index, scrubber, classifier = _index(), _scrubber(), _classifier()
    scaler = TemperatureScaler.load()
    bucket_of = dict(index.bucket)

    rows: list[dict[str, Any]] = []
    items = split(split_name)[:limit]
    scrubs = [scrubber.scrub(item.email.text) for item in items]
    classifications = classifier.predict_batch([s.text for s in scrubs])
    for item, scrub, classification in zip(items, scrubs, classifications, strict=True):
        bucket, summed = rollup(classification, bucket_of)
        score = calibrate(bucket, summed, scaler)
        rows.append({
            "id": item.email.id,
            "subject": item.email.subject or "(no subject)",
            "sender": item.email.sender or "unknown sender",
            "received_at": item.email.received_at,
            "body": scrub.text,
            "truth": item.label,
            "predicted": classification.label,
            "score": score,
            "flags": detect_flags(scrub.text, classification),
            "sop_ids": tuple(s.sop_id for s in index.sops_for(classification.label)),
        })
    return rows


@st.cache_resource
def _graph(multiplier: float) -> Any:
    """The compiled graph, built once per threshold multiplier.

    Rebuilding it per draft re-read the SOP corpus, re-loaded the temperature and
    re-constructed the Gemini client on every click; the deps exist to be resolved
    once at startup (``graph.py``), so caching here restores that.
    """
    return build_graph(
        build_default_deps(classifier=_classifier(), multiplier=multiplier)
    )


def _email_for(split_name: str, email_id: str) -> Any:
    """Look the email up by id rather than by position.

    Positional lookup indexed the FULL split with an offset computed inside the
    truncated ``rows`` list. They agree only while ``rows`` is an unfiltered prefix,
    so any future sort or filter of the queue would have drafted a reply to the
    wrong citizen's email -- silently, since both are valid emails.
    """
    for item in split(split_name):
        if item.email.id == email_id:
            return item.email
    raise KeyError(f"no email {email_id!r} in split {split_name!r}")


@st.cache_data
def _risk_coverage() -> dict[str, Any] | None:
    path = RESULTS / "risk_coverage.json"
    if not path.exists():
        return None
    return json.loads(path.read_text(encoding="utf-8"))


def _reason_chip(row: dict[str, Any], decision: Any) -> str:
    """One line saying why this item is in front of an officer.

    Covers all three escalation causes from ``BUILD.md`` S5.9. The threshold case
    shows both numbers, because "low confidence" without the comparison does not
    tell a reviewer whether the item was marginal or hopeless.
    """
    if decision.reason is None:
        return ""
    if decision.reason.value == "low_confidence":
        return f"low confidence {decision.confidence:.2f} < {decision.threshold:.2f}"
    return f"bucket requires review â€” {decision.reason.value.replace('_', ' ')}"


def _short_reason(decision: Any) -> str:
    """The reason chip, abbreviated to fit one queue row.

    The full sentence from :func:`_reason_chip` is what the detail pane shows; a
    row has one line, so the threshold case keeps both numbers -- which is the part
    that tells a reviewer whether the item was marginal -- and the structural cases
    drop the "bucket requires review" preamble, since sitting in the review queue
    already says that. The vocabulary stays closed either way, so the queue can
    still be grouped by it.
    """
    if decision.reason is None:
        return ""
    if decision.reason.value == "low_confidence":
        # A plain "<": the label is markdown, not HTML, so an escaped entity would
        # render literally.
        return f"{decision.confidence:.2f} < {decision.threshold:.2f}"
    return decision.reason.value.replace("_", " ")


def _queue_row(row: dict[str, Any], decision: Any, *, key_prefix: str) -> None:
    """One compact list row: subject, sender, timestamp and a status chip.

    The row is styled through its widget KEY: Streamlit stamps ``st-key-<key>`` on
    the element container, so a ``qrow-`` prefix gives the CSS above a stable hook,
    and a ``qrow-sel-`` prefix marks the open item -- which is what gives the list a
    visible selected state instead of leaving selection invisible in
    ``session_state``.

    Two lines in one label: the subject, then the routing outcome, any flags, the
    sender and the date. The outcome is coloured with Streamlit's ``:orange[...]``
    markdown rather than HTML, because a button label escapes raw markup.
    """
    selected = st.session_state.get("selected") == row["id"]
    key = f"qrow-{'sel-' if selected else ''}{key_prefix}{row['id']}"

    # Colour is carried by Streamlit's own markdown colour spans, which survive
    # inside a button label where raw HTML does not. Orange for escalation, green
    # for an auto-reply, violet for a redirect -- so the queue reads down its
    # status column without the officer parsing each line.
    if decision.action is Action.ESCALATE:
        chip_text = f":orange[{_short_reason(decision)}]"
    elif decision.action is Action.REDIRECT:
        chip_text = f":violet[redirect Â· {decision.confidence:.2f}]"
    else:
        chip_text = f":green[auto-reply Â· {decision.confidence:.2f}]"

    # The whole row is ONE button, subject and status in a single markdown label.
    # Drawing the status as a separate element above the button was tried first and
    # collides: Streamlit's inter-widget spacing cannot be negated reliably enough
    # to stack two elements into one visual row, and the chip landed on top of the
    # subject. Keeping it in the label also makes the entire row the click target.
    flag_text = "".join(f" Â· :red[{f.value.replace('_', ' ')}]" for f in row["flags"])
    stamp = row["received_at"].strftime("%d %b")

    if st.button(
        f"**{row['subject']}**  \n{chip_text}{flag_text} Â· {row['sender']} Â· {stamp}",
        key=key, use_container_width=True,
    ):
        st.session_state["selected"] = row["id"]
        st.rerun()


# --------------------------------------------------------------------------- #
# Sidebar
# --------------------------------------------------------------------------- #

st.sidebar.title("Controls")
split_name = st.sidebar.selectbox("Split", ["test", "calibration", "train"], index=0)
limit = st.sidebar.slider("Emails to load", 20, 200, 60, step=20)
multiplier = st.sidebar.slider(
    "Threshold multiplier", 0.2, 2.0, 1.0, step=0.05,
    help="Scales every per-bucket threshold. 1.0 is the configured operating point.",
)
drafting_on = st.sidebar.toggle(
    "Draft live", value=False,
    help="Calls the drafting model for the selected item. Free-tier rate limits are "
         "visible rather than hidden.",
)

thresholds = load_thresholds()
scaler = TemperatureScaler.load()
if not scaler.fitted:
    st.sidebar.warning("Calibration is not fitted â€” confidences are raw.")

st.sidebar.caption(
    f"temperature {scaler.temperature:.4f} Â· "
    f"auto_answerable threshold {thresholds.get('auto_answerable', 0.5) * multiplier:.2f}"
)


# --------------------------------------------------------------------------- #
# Route at the current multiplier
# --------------------------------------------------------------------------- #

try:
    rows = _triage(split_name, limit)
except ModelNotTrainedError as exc:
    st.error(f"The classifier is not trained yet.\n\n{exc}")
    st.caption(
        "Everything else in the pipeline is wired and will run as soon as the "
        "artefact exists â€” scrubbing, rollup, calibration, routing and the SOP pane "
        "all read from it."
    )
    st.stop()
except Exception as exc:  # noqa: BLE001 -- a broken pipeline is a message, not a stack
    st.error(f"Triage failed: {type(exc).__name__}: {exc}")
    st.exception(exc)
    st.stop()

index = _index()
decisions = [
    route(
        row["score"], index.sops_for(row["predicted"]), row["flags"],
        dict(thresholds), calibrated=scaler.fitted, multiplier=multiplier,
    )
    for row in rows
]

automated = [(r, d) for r, d in zip(rows, decisions, strict=True) if d.is_automated]
escalated = [(r, d) for r, d in zip(rows, decisions, strict=True) if not d.is_automated]

st.title("Citizen correspondence â€” officer queue")
left, middle, right = st.columns(3)
left.metric("Coverage", f"{len(automated) / max(len(rows), 1):.1%}",
            help="Share acted on without a human: auto-replies plus redirects.")
middle.metric("Auto-replied", len(automated))
right.metric("Needs review", len(escalated))


# --------------------------------------------------------------------------- #
# The two queues
# --------------------------------------------------------------------------- #

#: Queue-to-detail proportions. The queue needs enough width for a subject line to
#: survive without truncating, and the detail pane carries the SOP in full, so it
#: takes the larger share -- but not by as much as the earlier 1:1.4, which left the
#: list cramped while the detail pane sat half empty.
queue_col, detail_col = st.columns([1, 1.15], gap="medium")

with queue_col:
    auto_tab, review_tab = st.tabs(
        [f"Auto-replied ({len(automated)})", f"Needs review ({len(escalated)})"]
    )

    with auto_tab:
        if not automated:
            st.caption("Nothing was automated at this threshold.")
        for row, decision in automated:
            _queue_row(row, decision, key_prefix="a")

    with review_tab:
        if not escalated:
            st.caption("Nothing escalated at this threshold.")
        for row, decision in escalated:
            _queue_row(row, decision, key_prefix="e")


# --------------------------------------------------------------------------- #
# Detail pane
# --------------------------------------------------------------------------- #

with detail_col:
    selected_id = st.session_state.get("selected")
    pair = next(
        ((r, d) for r, d in zip(rows, decisions, strict=True) if r["id"] == selected_id),
        None,
    )

    if pair is None:
        st.info("Select an item from either queue.")
    else:
        row, decision = pair
        st.markdown(
            f"<div style='font-size:1.35rem;font-weight:650;line-height:1.3;"
            f"margin-bottom:2px'>{row['subject']}</div>"
            f"<div style='font-size:0.8rem;opacity:0.65;margin-bottom:10px'>"
            f"{row['sender']} Â· {row['received_at'].strftime('%d %b %Y, %H:%M')}</div>",
            unsafe_allow_html=True,
        )

        if decision.reason is not None:
            st.warning(_reason_chip(row, decision), icon="âš ï¸")
        else:
            st.success(f"{decision.action.value} Â· confidence {decision.confidence:.2f}")

        a, b, c = st.columns(3)
        a.caption(f"**Predicted**\n\n{row['predicted']}")
        b.caption(f"**Bucket**\n\n{decision.bucket.value}")
        c.caption(f"**Flags**\n\n{', '.join(f.value for f in row['flags']) or 'â€”'}")

        st.text_area("Email (scrubbed)", row["body"], height=180, disabled=True)
        st.caption(
            "Shown scrubbed, because this is exactly what the classifier and any "
            "external call saw. Real values never leave the machine."
        )

        # --- drafting -------------------------------------------------------
        if decision.is_automated:
            if drafting_on:
                with st.spinner("Drafting â€¦"):
                    try:
                        state = run_one(
                            _graph(multiplier),
                            TriageState(email=_email_for(split_name, row["id"])),
                        )
                        draft = state.draft
                    except Exception as exc:  # noqa: BLE001
                        draft = None
                        st.error(f"Drafting failed: {exc}")

                if draft is not None and draft.status.value == "ok":
                    st.markdown("**Draft reply**")
                    st.info(draft.text)
                    st.caption(f"Grounded on {', '.join(draft.grounded_on) or 'â€”'}")
                elif draft is not None:
                    reason = (
                        draft.failure_reason.value if draft.failure_reason else "unknown"
                    )
                    st.error(f"draft failed: {reason}")
                    st.caption(
                        "The item still carries its SOP below, so the officer can "
                        "write the reply from the same source the drafter would have used."
                    )
            else:
                st.caption("Enable **Draft live** in the sidebar to generate a reply.")

        # --- SOP pane -------------------------------------------------------
        st.divider()
        if not row["sop_ids"]:
            st.error(
                "No supporting SOP â€” this class has no indexed procedure, so there is "
                "nothing to ground a reply on. The item escalates by derivation."
            )
        else:
            st.markdown(f"**Procedure â€” {', '.join(row['sop_ids'])}**")
            for sop_id in row["sop_ids"]:
                sop = index.by_id.get(sop_id)
                if sop is None:
                    continue
                with st.expander(f"{sop.sop_id} â€” {sop.title}", expanded=len(row["sop_ids"]) == 1):
                    st.markdown(sop.body)


# --------------------------------------------------------------------------- #
# Risk-coverage
# --------------------------------------------------------------------------- #

st.divider()
curve = _risk_coverage()
if curve is None:
    st.caption("Run `python eval/run_eval.py` to produce the risk-coverage curve.")
else:
    st.subheader("Risk vs coverage")
    st.caption(
        "Swept with the real router over a global threshold multiplier. Reported per "
        "topic rather than as one inbox figure: an aggregate would need a class volume "
        "mix that is unpublished and seasonal."
    )
    try:
        import pandas as pd

        frame = (
            pd.DataFrame(curve["overall"])[["coverage", "risk"]]
            .groupby("coverage", as_index=True)
            .mean()
            .sort_index()
        )
        st.line_chart(frame)
        point = min(
            curve["overall"], key=lambda p: abs(p["multiplier"] - multiplier)
        )
        st.caption(
            f"At multiplier {point['multiplier']:.2f} â€” coverage {point['coverage']:.1%}, "
            f"risk {point['risk']:.1%} over {point['n']} emails. "
            f"AURC {curve.get('aurc_overall')}"
        )
    except ImportError:
        st.caption("pandas is needed for the chart.")

--- graph.py ---
"""LangGraph assembly -- the pipeline, wired.

RUNTIME. The one place the node order is stated, and the only module that knows
about all of them.

::

    scrub -> classify -> calibrate -> retrieve -> route -+-> draft    -> END
                                                         |
                                                         +-> declined -> END

LangGraph rather than a plain function chain, for one reason that pays off in this
domain: the execution path is a declared graph rather than an implicit consequence
of control flow, so "what happened to this email" is answerable by reading the
edges. High-stakes auditable workflows favour constrained patterns whose path is
traceable end to end (``BUILD.md`` S3).

**The conditional edge is the escalation gate made structural.** An escalated item
does not reach the drafting node at all -- not by an early return inside the drafter,
which a later edit could remove, but because no edge leads there. The router is the
single place that decision is made.

**Dependencies are injected at build time, not imported by the nodes.** The
classifier, SOP index, temperature and thresholds are bound into the graph by
:func:`build_graph`, so the ablation harness swaps a classifier or a temperature
without touching a node, and tests construct a graph with fakes and no model on
disk. A node that reached for a global would make both impossible.

**State merges rather than replaces.** Each node returns only the fields it sets;
``TriageState`` accumulates them, so a completed state is the full audit record of
one decision -- which is what the demo renders and what every metric reads.
"""

from __future__ import annotations

from collections.abc import Mapping
from dataclasses import dataclass
from typing import Any, Final

from langgraph.graph import END, StateGraph

from triage.llm.client import LLMClient, LLMError
from triage.models.base import Classifier
from triage.models.calibration import TemperatureScaler
from triage.nodes.calibrate import calibrate_node
from triage.nodes.classify import classify_node
from triage.nodes.draft import draft_node
from triage.nodes.flags import detect_flags
from triage.nodes.retrieve import retrieve_node
from triage.nodes.route import load_thresholds, route
from triage.nodes.scrub import scrub_node
from triage.schemas import (
    Action,
    Bucket,
    DraftResult,
    DraftStatus,
    EscalationReason,
    RoutingDecision,
    TriageState,
)
from triage.sop.index import SOPIndex, build_index

#: Confidence recorded when the pipeline could not produce one. The item escalates,
#: so the value is never compared against a threshold; 0.0 is the honest record of
#: "no confidence was obtained" rather than a score that might be read as measured.
_NO_CONFIDENCE: Final[float] = 0.0


@dataclass(frozen=True)
class GraphDeps:
    """Everything the nodes need, resolved once at startup.

    Assembled here rather than loaded per email: the SOP corpus is parsed and
    validated once, the classifier holds its weights, and the thresholds are read
    from config. A per-email reload would put a file-system error on the path of a
    citizen's enquiry.
    """

    classifier: Classifier
    index: SOPIndex
    scaler: TemperatureScaler
    thresholds: Mapping[str, float]
    client: LLMClient | None = None
    multiplier: float = 1.0

    @property
    def bucket_of(self) -> Mapping[str, str]:
        """class -> bucket, derived from SOP frontmatter."""
        return self.index.bucket


def _route_node(state: TriageState, deps: GraphDeps) -> dict[str, Any]:
    """Detect flags and make the escalation decision.

    Flag detection sits here rather than in its own node because it is an input to
    exactly one decision and has no other consumer -- a separate node would add a
    graph edge that never branches.

    An item that reached this point without a bucket score never got a usable
    prediction. It escalates as ``no_supporting_sop``: the pipeline has no grounds
    to act, and failing toward the officer is the only safe direction.
    """
    if state.bucket_score is None:
        return {
            "decision": RoutingDecision(
                action=Action.ESCALATE,
                bucket=Bucket.NO_SUPPORTING_SOP,
                confidence=_NO_CONFIDENCE,
                reason=EscalationReason.NO_SUPPORTING_SOP,
                calibrated=deps.scaler.fitted,
            ),
            "errors": [*state.errors, "routed without a prediction: escalating"],
        }

    text = state.scrub.text if state.scrub else state.email.text
    flags = detect_flags(text, state.classification)
    sops = tuple(deps.index.by_id[sid] for sid in state.sop_ids if sid in deps.index.by_id)

    decision = route(
        state.bucket_score,
        sops,
        flags,
        dict(deps.thresholds),
        calibrated=deps.scaler.fitted,
        multiplier=deps.multiplier,
    )
    return {"decision": decision}


def _should_draft(state: TriageState) -> str:
    """The conditional edge: only an item the router acted on reaches the drafter."""
    return "draft" if state.auto_reply_intended else "declined"


def _not_attempted(state: TriageState) -> dict[str, Any]:
    """Record that drafting was declined rather than skipped.

    An escalated item never reaches the drafting node -- that is the escalation gate
    being structural rather than a branch inside the drafter. But its ``draft``
    field must still be populated, because ``None`` is ambiguous: it reads equally
    as "the router declined" and as "the run stopped early". ``NOT_ATTEMPTED`` says
    which, so drafting availability counts only items drafting was actually asked
    for (``BUILD.md`` S5.8).
    """
    return {"draft": DraftResult(status=DraftStatus.NOT_ATTEMPTED, sop_ids=state.sop_ids)}


def build_graph(deps: GraphDeps) -> Any:
    """Compile the triage graph.

    Nodes are bound to ``deps`` here, so each remains ``pure(state) -> partial
    state`` and stays independently testable without a graph.
    """
    builder: StateGraph = StateGraph(TriageState)

    builder.add_node("scrub", scrub_node)
    builder.add_node("classify", lambda s: classify_node(s, deps.classifier))
    builder.add_node("calibrate", lambda s: calibrate_node(s, deps.bucket_of, deps.scaler))
    builder.add_node("retrieve", lambda s: retrieve_node(s, deps.index))
    builder.add_node("route", lambda s: _route_node(s, deps))
    builder.add_node("draft", lambda s: draft_node(s, deps.index, deps.client))
    builder.add_node("declined", _not_attempted)

    builder.set_entry_point("scrub")
    builder.add_edge("scrub", "classify")
    builder.add_edge("classify", "calibrate")
    builder.add_edge("calibrate", "retrieve")
    builder.add_edge("retrieve", "route")
    builder.add_conditional_edges(
        "route", _should_draft, {"draft": "draft", "declined": "declined"}
    )
    builder.add_edge("draft", END)
    builder.add_edge("declined", END)

    return builder.compile()


def build_default_deps(
    *,
    classifier: Classifier | None = None,
    drafting: bool = True,
    multiplier: float = 1.0,
) -> GraphDeps:
    """Assemble dependencies from what is on disk.

    Args:
        classifier: Overrides the fine-tuned encoder, for ablations and tests.
        drafting: When False, no LLM client is constructed. Every auto-reply then
            records a drafting failure, which is the correct behaviour for a
            routing-only eval sweep: the routing decision is unaffected, and
            drafting availability reports the absence honestly.
        multiplier: Scales every threshold. Swept to trace the risk-coverage curve.

    A missing ``GEMINI_API_KEY`` is not fatal. The item escalates to the officer
    carrying its SOP, exactly as a rate limit would -- the designed failure path
    rather than a special case (``BUILD.md`` S5.8).
    """
    if classifier is None:
        from triage.models.encoder import EncoderClassifier

        classifier = EncoderClassifier()

    client: LLMClient | None = None
    if drafting:
        from triage.llm.client import GeminiClient

        try:
            client = GeminiClient()
        except LLMError:
            client = None

    return GraphDeps(
        classifier=classifier,
        index=build_index(),
        scaler=TemperatureScaler.load(),
        thresholds=load_thresholds(),
        client=client,
        multiplier=multiplier,
    )


def run_one(graph: Any, state: TriageState) -> TriageState:
    """Run one email through a compiled graph and return the completed state.

    LangGraph returns the accumulated state as a mapping; it is validated back into
    a :class:`TriageState` so callers always receive the typed object.
    """
    result = graph.invoke(state)
    return result if isinstance(result, TriageState) else TriageState.model_validate(result)


__all__ = ["GraphDeps", "build_default_deps", "build_graph", "run_one"]

--- schemas.py ---
"""Typed state passed between graph nodes.

RUNTIME. Every node is ``pure(state) -> state``, so this module defines the only
contract between them. Nodes add fields; none removes or rewrites what an earlier
node wrote, which is what makes a completed :class:`TriageState` a full audit
record of how one email was handled -- the property the demo's reason chips and
the whole evaluation both read from.

Three modelling decisions here carry design weight rather than being convenience:

**Escalation reason is an enum, not a string.** It is reported per reason
(``BUILD.md`` S6.2), so a typo would silently create a seventh category and split
a metric. Six values, closed.

**A redirect is an automated action, not an escalation.** ``out_of_scope`` classes
auto-reply with a redirect, and that counts toward coverage under the no-back-door
policy (S5.6). Modelling it as an escalation would understate coverage on the
whole out-of-scope class.

**Drafting failure is separated from routing.** ``auto_reply_intended`` records
what the router decided; ``draft_status`` records what the drafter managed. A
Gemini rate-limit must never read back as "the router declined", or an outage
would leak into the risk-coverage curve, which is the headline result (S5.8).
"""

from __future__ import annotations

from datetime import datetime
from enum import StrEnum
from typing import Annotated, Self

from pydantic import BaseModel, ConfigDict, Field, model_validator

#: Tolerance on a softmax summing to 1.0. Wide enough for float error accumulated
#: across the class set plus a temperature division, tight enough that a genuinely
#: malformed distribution -- a truncated dict, or scores that were never softmaxed
#: -- still fails.
_PROB_SUM_TOLERANCE: float = 1e-3

# --------------------------------------------------------------------------- #
# Enumerations
# --------------------------------------------------------------------------- #


class Bucket(StrEnum):
    """The five routing buckets (``sop_design.md`` S3).

    Mirrors ``triage.sop.index``, which derives the class -> bucket map from SOP
    frontmatter. Duplicated as an enum so the schema layer can be imported without
    loading the corpus, and cross-checked in tests rather than by inheritance.
    """

    AUTO_ANSWERABLE = "auto_answerable"
    REQUIRES_ACCOUNT_LOOKUP = "requires_account_lookup"
    HIGH_CONSEQUENCE = "high_consequence"
    OUT_OF_SCOPE = "out_of_scope"
    NO_SUPPORTING_SOP = "no_supporting_sop"


class EscalationReason(StrEnum):
    """Why an item went to the human queue. Reported per reason, so closed.

    Ordered by the router's precedence. The first four are structural -- they never
    consult the classifier's confidence and would fire identically at probability
    1.0. Only ``LOW_CONFIDENCE`` reads the calibrated score.
    """

    REQUIRES_ACCOUNT_LOOKUP = "requires_account_lookup"
    HIGH_CONSEQUENCE = "high_consequence"
    NO_SUPPORTING_SOP = "no_supporting_sop"
    COMPUTATION_REQUESTED = "computation_requested"
    ACCOUNT_SPECIFIC_SIGNAL = "account_specific_signal"
    FOREIGN_INCOME_SIGNAL = "foreign_income_signal"
    SCAM_SIGNAL = "scam_signal"
    LOW_CONFIDENCE = "low_confidence"


class Flag(StrEnum):
    """Signals that cut ACROSS classes, so they cannot be classes themselves.

    Detected after the bucket rollup and applied to a class the SOP declares them
    for, which keeps the taxonomy a clean partition (``sop_design.md`` S3.1).

    ``COMPUTATION_REQUESTED`` gates the rule the corpus exists to enforce: the
    agent never computes a tax or relief amount. ``ACCOUNT_SPECIFIC_SIGNAL`` is a
    backstop for a known taxonomy compromise -- ``account_specific`` is a class but
    structurally a flag, and topical vocabulary dominates the one-or-two-token
    possessive signal, so the confusion lands on the unsafe side (``BUILD.md``
    S9.6).

    ``MULTI_INTENT`` is free: two high-scoring classes IS multi-intent, and the
    distribution already exists. It is informational and does not itself escalate.
    """

    COMPUTATION_REQUESTED = "computation_requested"
    ACCOUNT_SPECIFIC_SIGNAL = "account_specific_signal"
    #: Two MISFILE guards. Unlike the flags above, these do not mark a condition
    #: that cuts across an otherwise-correct classification -- they catch the
    #: classifier putting an email in the wrong class, in the one direction where
    #: that error is unsafe. ``FOREIGN_INCOME_SIGNAL`` guards residency against
    #: absorbing a held-out foreign-income question; ``SCAM_SIGNAL`` guards the
    #: redirect SOPs against sending a fraud victim to another agency. Both
    #: triggers are declared in SOP frontmatter (SOP-RES-001, SOP-RTE-002), so the
    #: corpus already asked for them.
    FOREIGN_INCOME_SIGNAL = "foreign_income_signal"
    SCAM_SIGNAL = "scam_signal"
    MULTI_INTENT = "multi_intent"


class Action(StrEnum):
    """What the system did with an item.

    ``REDIRECT`` is deliberately distinct from ``AUTO_REPLY`` and from
    ``ESCALATE``: it is an automated action that counts toward coverage, but its
    content is a redirect rather than a substantive answer, so the two are reported
    separately (S5.6).
    """

    AUTO_REPLY = "auto_reply"
    REDIRECT = "redirect"
    ESCALATE = "escalate"


class DraftStatus(StrEnum):
    """Whether drafting produced text. Independent of the routing decision."""

    OK = "ok"
    FAILED = "failed"
    NOT_ATTEMPTED = "not_attempted"


class DraftFailure(StrEnum):
    """Why a draft call failed. Free-tier rate limits fire during eval sweeps, so
    this path is exercised rather than hypothetical (``BUILD.md`` S5.8)."""

    RATE_LIMIT = "rate_limit"
    TIMEOUT = "timeout"
    API_ERROR = "api_error"


# --------------------------------------------------------------------------- #
# Inbox
# --------------------------------------------------------------------------- #


class Email(BaseModel):
    """One inbound citizen email -- the pipeline's entry point.

    ``received_at`` is load-bearing rather than metadata: it drives the seasonality
    axis (filing Mar-Apr, estimates May-Jun, NOA Jun-Jul), so an evaluation slice
    can ask whether performance holds across the tax year.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    id: str = Field(min_length=1)
    received_at: datetime
    subject: str = ""
    body: str = Field(min_length=1)
    sender: str | None = Field(default=None, alias="from")

    @property
    def text(self) -> str:
        """Subject and body as one string -- what the classifier sees.

        Joined rather than classified separately: a subject line often carries the
        intent ("GIRO deduction failed") while the body carries the detail, and
        splitting them would discard the strongest short signal in the message.
        """
        return f"{self.subject}\n\n{self.body}".strip()


# --------------------------------------------------------------------------- #
# Node outputs
# --------------------------------------------------------------------------- #


class ScrubRecord(BaseModel):
    """What the scrub node removed, and what is needed to reverse it.

    The vault stays in local state and is never sent anywhere. Rehydration happens
    locally after the draft returns, so real identifiers exist only on this machine.
    """

    model_config = ConfigDict(extra="forbid")

    text: str
    vault: dict[str, str] = Field(default_factory=dict, repr=False)
    counts: dict[str, int] = Field(default_factory=dict)

    @property
    def redacted_count(self) -> int:
        return len(self.vault)


class Classification(BaseModel):
    """The classifier's output: a label and the full distribution behind it.

    ``probabilities`` is kept in full rather than reduced to a top score, because
    the bucket rollup sums within-bucket probabilities and ``multi_intent`` reads
    the second-highest. Discarding the distribution would cost both for no saving.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    label: str = Field(min_length=1)
    probabilities: dict[str, float]
    model_name: str = "unknown"

    @model_validator(mode="after")
    def _check_distribution(self) -> Self:
        if self.label not in self.probabilities:
            raise ValueError(f"label {self.label!r} absent from the distribution")
        total = sum(self.probabilities.values())
        if abs(total - 1.0) > _PROB_SUM_TOLERANCE:
            raise ValueError(f"probabilities sum to {total:.6f}, expected 1.0")
        return self

    @property
    def confidence(self) -> float:
        """Raw, uncalibrated probability of the predicted label.

        Systematically overconfident: a network reporting 0.95 may be right 85% of
        the time. That gap is what the project measures, and it is why this value
        must not be compared against a threshold directly -- use
        :attr:`RoutingDecision.confidence`, which is calibrated.
        """
        return self.probabilities[self.label]

    @property
    def runner_up(self) -> tuple[str, float] | None:
        """Second-highest class and its probability, for ``multi_intent``."""
        ranked = sorted(self.probabilities.items(), key=lambda kv: -kv[1])
        return ranked[1] if len(ranked) > 1 else None


class BucketScore(BaseModel):
    """The distribution rolled up from the class set into 5 buckets.

    Calibration and thresholds live at this level, not at class level: at 1,800
    emails a bucket carries ~108 test examples against ~45 for a class, and a
    threshold set on 45 is not defensible -- the binomial interval is wider than the
    effect (``sop_design.md`` S3).
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    bucket: Bucket
    raw: Annotated[float, Field(ge=0.0, le=1.0)]
    calibrated: Annotated[float, Field(ge=0.0, le=1.0)] | None = None

    @property
    def confidence(self) -> float:
        """Calibrated confidence where it exists, else raw.

        Falling back is deliberate: the pipeline must run end to end before
        calibration is fitted. Whether a reported number came from the fitted
        temperature is recorded on :attr:`RoutingDecision.calibrated`, so a
        placeholder figure can never be mistaken for a result.
        """
        return self.raw if self.calibrated is None else self.calibrated


class RoutingDecision(BaseModel):
    """The escalation decision -- the system's contribution, in one object.

    Invariants enforced below rather than left to the router's control flow, since
    a routing bug is a citizen-facing failure and must not depend on a branch being
    written correctly.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    action: Action
    bucket: Bucket
    confidence: Annotated[float, Field(ge=0.0, le=1.0)]
    threshold: Annotated[float, Field(ge=0.0, le=1.0)] | None = None
    reason: EscalationReason | None = None
    flags: frozenset[Flag] = frozenset()
    #: False while the placeholder threshold is in force. A number produced under
    #: a placeholder must never be reported (``BUILD.md`` S7).
    calibrated: bool = False

    @model_validator(mode="after")
    def _reason_matches_action(self) -> Self:
        if self.action is Action.ESCALATE and self.reason is None:
            raise ValueError("an escalated item must carry an escalation reason")
        if self.action is not Action.ESCALATE and self.reason is not None:
            raise ValueError(f"{self.action} must not carry an escalation reason")
        return self

    @model_validator(mode="after")
    def _always_escalate_buckets_escalate(self) -> Self:
        """Three buckets escalate regardless of confidence, and an empty SOP lookup
        escalates by derivation. Asserted here so no confidence value, and no
        future edit to the router, can produce an auto-reply for them.
        """
        always = {
            Bucket.REQUIRES_ACCOUNT_LOOKUP,
            Bucket.HIGH_CONSEQUENCE,
            Bucket.NO_SUPPORTING_SOP,
        }
        if self.bucket in always and self.action is not Action.ESCALATE:
            raise ValueError(f"bucket {self.bucket} must always escalate, got {self.action}")
        return self

    @model_validator(mode="after")
    def _redirect_only_for_out_of_scope(self) -> Self:
        if self.action is Action.REDIRECT and self.bucket is not Bucket.OUT_OF_SCOPE:
            raise ValueError(f"redirect is only valid for out_of_scope, got {self.bucket}")
        if self.action is Action.AUTO_REPLY and self.bucket is not Bucket.AUTO_ANSWERABLE:
            raise ValueError(f"auto_reply is only valid for auto_answerable, got {self.bucket}")
        return self

    @property
    def is_automated(self) -> bool:
        """Whether the system acted without a human.

        A redirect counts: under the no-back-door policy a clean redirect is the
        correct outcome, not a failure, so it belongs in the coverage numerator
        (``BUILD.md`` S5.6).
        """
        return self.action in (Action.AUTO_REPLY, Action.REDIRECT)


class DraftResult(BaseModel):
    """The drafter's output, or the reason there is none.

    ``sop_ids`` is always populated, even on failure: the officer working the
    review queue writes the reply from the same source the drafter would have used,
    so a failure costs a paraphrase rather than the research (``BUILD.md`` S5.8).

    ``grounded_on`` is what the draft actually cited, and is compared against the
    scenario spec's source SOP to measure grounding accuracy (S9.2). It applies to
    ``tax_reliefs`` and ``payment``, the two classes that pull a group.
    """

    model_config = ConfigDict(frozen=True, extra="forbid")

    status: DraftStatus
    text: str | None = None
    failure_reason: DraftFailure | None = None
    sop_ids: tuple[str, ...] = ()
    grounded_on: tuple[str, ...] = ()
    model_name: str | None = None

    @model_validator(mode="after")
    def _status_matches_payload(self) -> Self:
        if self.status is DraftStatus.OK and not self.text:
            raise ValueError("a successful draft must carry text")
        if self.status is DraftStatus.FAILED and self.failure_reason is None:
            raise ValueError("a failed draft must carry a failure reason")
        if self.status is not DraftStatus.FAILED and self.failure_reason is not None:
            raise ValueError("only a failed draft may carry a failure reason")
        return self


# --------------------------------------------------------------------------- #
# Graph state
# --------------------------------------------------------------------------- #


class TriageState(BaseModel):
    """Everything known about one email, accumulated across the graph.

    Nodes append; nothing is overwritten. A completed state is therefore the audit
    record for one decision -- which is what the demo's reason chips render and what
    every evaluation metric reads.
    """

    model_config = ConfigDict(extra="forbid")

    email: Email
    scrub: ScrubRecord | None = None
    classification: Classification | None = None
    bucket_score: BucketScore | None = None
    sop_ids: tuple[str, ...] = ()
    decision: RoutingDecision | None = None
    draft: DraftResult | None = None
    #: Node-level failures that did not stop the run, for the demo and for triage.
    errors: list[str] = Field(default_factory=list)

    @property
    def auto_reply_intended(self) -> bool:
        """Whether the ROUTER chose to act, regardless of what drafting managed.

        The load-bearing distinction of ``BUILD.md`` S5.8. A drafting failure must
        not read back as a routing decision: a rate-limit says nothing about
        whether the email was safe to auto-reply, and if it leaked into the routing
        signal a Gemini outage would corrupt the risk-coverage curve.
        """
        return self.decision is not None and self.decision.is_automated

    @property
    def draft_failed(self) -> bool:
        return self.draft is not None and self.draft.status is DraftStatus.FAILED

    @property
    def in_human_queue(self) -> bool:
        """Items an officer must work: escalations, plus drafting failures.

        Two different populations sharing one queue. ``auto_reply_intended``
        separates them for evaluation.
        """
        if self.decision is None:
            return True  # incomplete run: fail safe toward the human
        return not self.decision.is_automated or self.draft_failed

    @property
    def queue_reason(self) -> str | None:
        """Why this item is in the human queue -- the demo's reason chip.

        A drafting failure is reported as ``draft_failed: <cause>`` and never as an
        escalation reason, so the two remain separable downstream.
        """
        if self.draft_failed and self.decision is not None and self.decision.is_automated:
            assert self.draft is not None and self.draft.failure_reason is not None
            return f"draft_failed: {self.draft.failure_reason}"
        if self.decision is not None and self.decision.reason is not None:
            return str(self.decision.reason)
        return None

    def redacted(self) -> TriageState:
        """A copy safe to write to disk: no vault, no unscrubbed text.

        The ordinary serialisation of this state contains raw PII by design -- the
        vault holds real identifiers so the draft can be rehydrated locally, and
        ``email.body`` is the message as received. That is correct in memory and
        wrong on disk, because ``eval/results/`` is committed to the repository and
        the demo writes its queues out.

        This method is the boundary. It replaces the email text with the scrubbed
        form, empties the vault, and keeps the redaction *counts*, which is what
        scrub-recall reporting actually needs. Anything persisted or displayed goes
        through here; nothing else should serialise a :class:`TriageState`.

        Falls back to redacting the body entirely if scrubbing has not run, rather
        than passing the original through -- a state that never reached the scrub
        node must not be written out on the assumption that it was clean.
        """
        if self.scrub is None:
            safe_body = "[UNSCRUBBED - REDACTED]"
            safe_subject = "[UNSCRUBBED - REDACTED]"
        else:
            safe_body = self.scrub.text
            safe_subject = ""

        return self.model_copy(
            update={
                "email": self.email.model_copy(
                    update={"body": safe_body, "subject": safe_subject, "sender": None}
                ),
                "scrub": (
                    None
                    if self.scrub is None
                    else ScrubRecord(text=self.scrub.text, vault={}, counts=self.scrub.counts)
                ),
            }
        )


__all__ = [
    "Action",
    "Bucket",
    "BucketScore",
    "Classification",
    "DraftFailure",
    "DraftResult",
    "DraftStatus",
    "Email",
    "EscalationReason",
    "Flag",
    "RoutingDecision",
    "ScrubRecord",
    "TriageState",
]

--- env.py ---
"""Load ``.env`` into the process environment.

RUNTIME and EVAL-TIME.

``.env.example`` tells a grader to copy the file and fill in their keys, and every
client reads its key from :data:`os.environ`. Without something bridging the two,
a correctly-populated ``.env`` has no effect and the system behaves exactly as it
would with no key at all -- drafting fails on every item, the judge is skipped, and
the failure looks like a missing key rather than a missing loader. That silence is
the reason this module exists rather than being folded into each client.

**Existing environment variables always win.** A value already exported is a
deliberate act -- CI, a container, a one-off override on the command line -- and a
file on disk must not overwrite it. So this fills gaps rather than assigning.

**Never raises.** A missing ``.env`` is normal: keys may come from the real
environment, and the runtime is designed to degrade honestly when a key is absent
(a failed draft escalates carrying its SOP). Turning a missing file into a crash
would take a working degraded path and break it.

No dependency on ``python-dotenv``: the format needed here is a few lines of
``KEY=value``, and parsing it directly keeps one less package in a runtime that has
to install cleanly on a grader's machine.
"""

from __future__ import annotations

import os
from pathlib import Path
from typing import Final

#: Repository root, from this file.
DEFAULT_ENV: Final[Path] = Path(__file__).resolve().parents[2] / ".env"


def load_env(path: Path | None = None, *, override: bool = False) -> dict[str, str]:
    """Read ``KEY=value`` lines into ``os.environ``.

    Args:
        path: The file to read. Defaults to ``.env`` at the repository root.
        override: When True, replace variables already set. Off by default, so an
            exported value beats the file.

    Returns:
        The names that were actually set, mapped to their source. Names only --
        a secret must not be returned to a caller that might log it.
    """
    source = path or DEFAULT_ENV
    if not source.exists():
        return {}

    applied: dict[str, str] = {}
    for raw in source.read_text(encoding="utf-8").splitlines():
        line = raw.strip()
        if not line or line.startswith("#") or "=" not in line:
            continue

        key, _, value = line.partition("=")
        key = key.strip()
        value = value.strip().strip('"').strip("'")
        if not key or not value:
            continue

        if override or not os.environ.get(key):
            os.environ[key] = value
            applied[key] = str(source)

    return applied


def key_status() -> dict[str, bool]:
    """Which keys are present, without revealing any of them.

    Printed by entrypoints so a run states up front what it can and cannot do --
    an eval that silently skipped the judge is worse than one that said so.

    The numbered Gemini variables are optional fallbacks. Free-tier drafting quota
    is a daily budget, so an exhausted key stays exhausted for hours; a second key
    lets a sweep or a demo carry on rather than stopping. Absent ones are reported
    False rather than omitted, so the status line shows how much headroom a run
    actually has.
    """
    return {
        name: bool(os.environ.get(name))
        for name in (
            "GEMINI_API_KEY",
            "GEMINI_API_KEY_2",
            "GEMINI_API_KEY_3",
            "GROQ_API_KEY",
            "OPENAI_API_KEY",
        )
    }


__all__ = ["DEFAULT_ENV", "key_status", "load_env"]

